(() => {
'use strict';
const content=window.HUB_CONTENT, competencies=content.rubric.competencies.map(c=>({...c,group:({people:'people_leader',senior:'senior_leader'})[c.group]||c.group})), guides=content.development;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',path:'M5 20V6a3 3 0 0 1 6 0v12a3 3 0 0 0 6 0V4m-3 3 3-3 3 3',leaf:'M20 3c-10-1-17 4-15 11 2 7 16 5 15-11ZM4 21 16 8',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m7 .13a4 4 0 0 1 0 7.75',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2m3 10h3m-3 4h6',book:'M12 5v16m0-16C9 3 5 3 2 4v16c3-1 7-1 10 1m0-16c3-2 7-2 10-1v16c-3-1-7-1-10 1',check:'M8 3H5v18h14V3h-3M8 2h8v4H8zM8 13l3 3 5-6',arrow:'M5 12h14m-5-5 5 5-5 5',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',bolt:'m13 2-9 12h7l-1 8 10-12h-7l1-8',message:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4ZM8 9h8m-8 4h5',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4ZM8 12l3 3 5-6',target:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 5a5 5 0 1 0 0 10 5 5 0 0 0 0-10m0 4v2',flag:'M4 22V3m0 0c6-4 10 5 16 0v11c-6 5-10-4-16 0',info:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 9v6m0-10v.1'};
const icon=(key,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[key]||icons.layers}"/></svg>`;
const competencyIcon={'action-oriented':'bolt','self-development':'leaf','communicates-effectively':'message','customer-focus':'heart','instills-trust':'shield','collaborates':'people','develops-talent':'leaf','ensures-accountability':'check','strategic-mindset':'target','drives-vision-purpose':'flag'};
const roles={nxs:'Non-Exempt Step',nxt:'Non-Exempt Traditional',exempt:'Exempt',people_leader:'People Leader',senior_leader:'Senior Leader'};
const groupLabels={core:'All employees',people_leader:'People Leaders',senior_leader:'Senior Leaders'};
const state={search:'',filter:'all',role:'exempt',tab:'behaviors',planCompetency:'communicates-effectively',plans:{},reviewFrame:null};
const byId=id=>competencies.find(c=>c.id===id), guideById=id=>guides.find(c=>c.id===id), sourceRole=role=>content.rubric.roleMapping[role], developmentRole=role=>(role==='nxs'||role==='nxt')?'non_exempt':role;
const hasRole=(c,role)=>Boolean(c.roles[sourceRole(role)]), roleOptions=(selected,comp)=>Object.entries(roles).filter(([v])=>!comp||hasRole(comp,v)).map(([v,label])=>`<option value="${v}" ${v===selected?'selected':''}>${label}</option>`).join('');
function routeHref(route){return '#'+route}
function footer(){return '<footer><span>Southwest Gas · Human Resources · Talent Development</span><a href="#resources">Sources & support</a></footer>'}
function sectionHeading(eyebrow,title,description='',link=''){return `<div class="section-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${link}</div>`}
function heading(eyebrow,title,description){return `<header class="page-heading"><span class="eyebrow">${eyebrow}</span><h1 tabindex="-1">${title}</h1><p>${description}</p></header>`}
function card(c){const group=c.group==='core'?'':c.group==='people_leader'?'leader':'senior';return `<a class="competency-card ${group}" href="#competency/${c.id}"><span class="card-icon">${icon(competencyIcon[c.id])}</span><h3>${esc(c.name)}</h3><p>${esc(c.definition)}</p><span class="card-bottom"><span>Explore competency</span>${icon('arrow')}</span></a>`}
function home(){return `<section class="hero"><div class="brand-label"><span>SOUTHWEST GAS</span><span>HUMAN RESOURCES</span></div><span class="eyebrow">ONE MODEL. EVERYDAY APPLICATION.</span><h1 tabindex="-1">Build capability.<br>Grow your contribution.</h1><p>Understand the competencies that connect our work. Explore what they look like in your role and find a practical place to begin.</p><div class="hero-actions"><a class="button yellow" href="#competencies">Explore the competencies ${icon('arrow')}</a><a class="button secondary" href="#stages">Find your contribution level</a></div><div class="model-strip" aria-label="Five core competencies, plus three for People Leaders, plus two for Senior Leaders"><a href="#competencies/core"><strong>5</strong><span>Core competencies<br>for everyone</span></a><span class="plus" aria-hidden="true">+</span><a href="#competencies/people_leader"><strong>3</strong><span>Additional for<br>People Leaders</span></a><span class="plus" aria-hidden="true">+</span><a href="#competencies/senior_leader"><strong>2</strong><span>Additional for<br>Senior Leaders</span></a></div></section>
<div class="notice">${icon('info')}<p><strong>Start with learning and practice.</strong> The new model and definitions are final. Supporting behaviors and review design are still being refined. The 2026 review cycle continues under the existing process. <a href="#implementation">See the implementation plan</a>.</p></div>
<section class="section">${sectionHeading('THE FOUNDATION','Five competencies we all share','A common language for how we work, support others, and keep improving.',`<a class="text-link" href="#competencies">View the full model ${icon('arrow',17)}</a>`)}<div class="core-grid">${competencies.filter(c=>c.group==='core').map(card).join('')}<div class="model-note"><span class="eyebrow">AS RESPONSIBILITY GROWS</span><h3>Build on the foundation.</h3><p>People Leaders add three competencies. Senior Leaders build on all eight with two more.</p><a class="text-link" href="#competencies/people_leader">Explore leadership competencies ${icon('arrow',17)}</a></div></div></section>
<section class="section">${sectionHeading('MAKE IT PRACTICAL','From understanding to action')}<div class="two-columns"><article class="panel">${icon('leaf',29)}<h3>Choose one thing to work on.</h3><p>Find a relevant behavior, try a practical action, and plan how you’ll recognize progress.</p><a class="button secondary" href="#development">Build a development plan ${icon('arrow')}</a></article><article class="panel">${icon('people',29)}<h3>Make room for a conversation.</h3><p>Use the model to recognize strengths, discuss real work, and agree on a useful next step.</p><a class="button secondary" href="#leader">Open leader conversation tools ${icon('arrow')}</a></article></div></section>
<section class="section">${sectionHeading('A SHARED DIRECTION','Know what’s changing','The new competencies are already used in Talent Acquisition. Broader implementation follows a phased plan.')}<div class="two-columns"><article class="panel"><span class="eyebrow">NOW · 2026</span><h3>Build a shared understanding.</h3><p>Learn the language, connect it to daily work, and use it in development conversations.</p><a class="text-link" href="#implementation">View the full timeline ${icon('arrow',17)}</a></article><article class="panel"><span class="eyebrow">WHAT COMES NEXT</span><h3>Practice. Prepare. Implement.</h3><p>Training and readiness in 2027. Full implementation in November 2027 for Exempt and NXT, followed by NXS in April 2028.</p><a class="text-link" href="#resources">Find answers to common questions ${icon('arrow',17)}</a></article></div></section>
<section class="review-feature"><div><span class="eyebrow">WHEN IT’S TIME TO REVIEW</span><h2>Performance review workspace</h2><p>Prepare behavior ratings, comments, and a review summary for manual entry into Oracle. Explore the future review design using fictional employees.</p><span class="pill">Design preview · Session-only entries</span></div><a class="button" href="#reviews">Open performance reviews ${icon('arrow')}</a></section>`}
function catalog(){return heading('EXPLORE THE MODEL','Competencies, connected.','Start with a competency, or choose your role to see the competencies that apply to you.')+`<div class="toolbar"><div class="field search"><label for="competency-search">Find a competency</label><div class="search-wrap">${icon('search',19)}<input id="competency-search" type="search" value="${esc(state.search)}" placeholder="Search names, definitions, or behaviors" autocomplete="off"></div></div><div class="field"><label for="catalog-role">Show competencies for</label><select id="catalog-role"><option value="all" ${state.filter==='all'?'selected':''}>All roles · Full model</option>${roleOptions(state.filter)}</select></div></div><div class="filters" aria-label="Competency groups">${[['all','All competencies'],['core','Core · 5'],['people_leader','People Leader additions · 3'],['senior_leader','Senior Leader additions · 2']].map(([v,t])=>`<button class="filter" type="button" data-group="${v}" aria-pressed="${(state.group||'all')===v}">${t}</button>`).join('')}</div><div id="catalog-results">${catalogResults()}</div>`}
function catalogResults(){const q=state.search.trim().toLowerCase();const filtered=competencies.filter(c=>(state.filter==='all'||hasRole(c,state.filter))&&(!state.group||state.group==='all'||c.group===state.group)&&(!q||[c.name,c.definition,...Object.values(c.roles).flatMap(r=>r.behaviors.map(b=>b.statement))].join(' ').toLowerCase().includes(q)));return `<p class="result-meta" role="status">${filtered.length} ${filtered.length===1?'competency':'competencies'}${state.filter!=='all'?' for '+roles[state.filter]:''}${q?' matching “'+esc(state.search.trim())+'”':''}</p>`+(filtered.length?['core','people_leader','senior_leader'].map(group=>{const list=filtered.filter(c=>c.group===group);return !list.length?'':`<section class="catalog-group"><h2><span class="count">${list.length}</span>${group==='core'?'The foundation for everyone':group==='people_leader'?'Additional for People Leaders':'Additional for Senior Leaders'}</h2><p>${group==='core'?'These five competencies apply at every level.':group==='people_leader'?'Three more competencies for those who lead others.':'Two more competencies for those who shape organizational direction.'}</p><div class="core-grid">${list.map(card).join('')}</div></section>`}).join(''):`<div class="empty-state">${icon('search',32)}<h2>No matching competencies</h2><p>Try a broader word, or reset the filters to explore the full model.</p><button type="button" class="button secondary" data-action="reset-search">Reset search and filters</button></div>`)}
function stages(){return heading('CONTRIBUTION BY ROLE','The same model. A broader contribution.','Stages describe how contribution grows with responsibility and complexity. They guide development conversations; they are not performance ratings.')+`<div class="panel"><div class="step-rail">${content.playbook.stages.map((s,i)=>`<article class="stage-card"><span class="stage-number">${i+1}</span><div><span class="pill">${esc(s.employeeLevel)}</span><h3>${esc(s.stage)}</h3><p><strong>${esc(s.focus)}.</strong> ${esc(s.primaryContribution)}.</p><a class="text-link" href="#competencies/role/${['nxt','exempt','people_leader','senior_leader'][i]}">Explore competencies for this level ${icon('arrow',17)}</a></div></article>`).join('')}</div></div><p class="source-note">Source: Director Champion Playbook, Section 6. Individual Contributor stage wording is still being refined. Exempt and Non-Exempt Traditional share behavior wording in the current draft rubric; their contribution stages remain distinct.</p><section class="section">${sectionHeading('CHOOSE YOUR VIEW','See the behaviors for your role')}<div class="toolbar"><div class="field search"><label for="stage-role">Your role</label><select id="stage-role">${roleOptions(state.role)}</select></div><a class="button" id="stage-explore" href="#competencies/role/${state.role}">Explore this role ${icon('arrow')}</a></div></section>`}
function currentGuide(){return byId(location.hash.split('/')[1])}
function guidePage(c){if(!hasRole(c,state.role))state.role=c.group==='senior_leader'?'senior_leader':'people_leader';return `<a class="breadcrumb" href="#competencies">← All competencies</a><header class="guide-hero"><span class="pill">${esc(groupLabels[c.group])}${c.group==='people_leader'?' & Senior Leaders':''}</span><h1 tabindex="-1">${esc(c.name)}</h1><p>${esc(c.definition)}</p><div class="guide-source">Definition: current Southwest Gas competency rubric · ${esc(c.sourceSheet)}, ${c.definitionSourceCell}</div></header><div class="guide-controls"><div class="field"><label for="guide-role">Explore this competency as a</label><select id="guide-role">${roleOptions(state.role,c)}</select></div><p>The definition stays the same. The way you apply it grows with your role and responsibility.</p></div><nav class="tabs" aria-label="Competency guide sections">${[['behaviors','Behaviors by role'],['practice','Put it into practice'],['plan','Make a plan']].map(([v,t])=>`<button type="button" data-guide-tab="${v}" aria-pressed="${state.tab===v}">${t}</button>`).join('')}</nav><div id="guide-body" class="guide-body">${guideBody(c)}</div>`}
function guideBody(c){const g=guideById(c.id),r=c.roles[sourceRole(state.role)],dr=g.roles[developmentRole(state.role)];if(state.tab==='plan')return planForm(c);if(state.tab==='practice')return `<div class="note"><strong>Ideas for development.</strong> These practical suggestions come from the original hub and are not additional rating criteria or Korn Ferry source text.</div><div class="panel"><span class="eyebrow">START WITH THE WORK</span><h2>Build ${esc(c.name.toLowerCase())} into your day.</h2><p>${esc(g.why[0])}</p></div><section class="section">${sectionHeading('TRY ONE PRACTICAL ACTION','Practice, then reflect')}<div class="stack">${dr.practice.map(p=>`<article class="panel"><h3>${esc(p.title)}</h3><p>${esc(p.action)}</p><div class="note"><strong>Look for progress:</strong> ${esc(p.evidence)}</div></article>`).join('')}</div></section><section class="section"><div class="two-columns"><article class="panel"><h3>Questions to think through</h3><ul>${dr.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></article><article class="panel"><h3>Turn an idea into a commitment.</h3><p>Choose one action, the support you need, and a time to reflect on what changed.</p><button class="button" data-guide-tab="plan" type="button">Make a development plan ${icon('arrow')}</button></article></div></section><section class="section"><h2>Related competencies</h2><div class="filters">${g.related.filter(id=>byId(id)).map(id=>`<a class="filter" href="#competency/${id}">${esc(byId(id).name)}</a>`).join('')}</div></section>`;
return `<div class="notice">${icon('info')}<p><strong>Use these behaviors for awareness and discussion.</strong> Supporting behaviors are still being refined. They are not final evaluation expectations.</p></div><section class="section">${sectionHeading(roles[state.role], 'What this can look like in your work')}<ol class="behavior-list">${r.behaviors.map((b,i)=>`<li><span class="number">${i+1}</span><div><strong>${esc(b.statement)}</strong><small>Current rubric · ${esc(c.sourceSheet)} · ${b.sourceCell}</small></div></li>`).join('')}</ol><p class="source-note">Exact behavior wording from the current rubric. ${state.role==='nxt'?'Non-Exempt Traditional uses the Exempt & NXT behavior set. ':''}Ratings and rating anchors are available within the future performance review workspace.</p></section><section class="section"><div class="two-columns"><article class="panel"><span class="eyebrow">A USEFUL CONVERSATION</span><h3>Connect the behavior to real work.</h3><p>${esc(dr.questions[0])}</p><p>Discuss a specific example, what it changed, and what would help you do it more consistently.</p></article><article class="panel"><span class="eyebrow">YOUR NEXT STEP</span><h3>Make it practical.</h3><p>Explore role-specific examples and practice ideas, then choose one action you can try.</p><button class="button secondary" data-guide-tab="practice" type="button">Explore practice ideas ${icon('arrow')}</button></article></div></section>`}
function planKey(c){return c.id+':'+state.role}
function getPlan(c){return state.plans[planKey(c)]||{action:'',support:'',evidence:'',date:'',reflection:''}}
function planForm(c){const p=getPlan(c);return `<section class="panel"><span class="eyebrow">ONE COMPETENCY. ONE PRACTICAL COMMITMENT.</span><h2>My development plan</h2><p>${esc(c.name)} · ${roles[state.role]}</p><div class="note"><strong>Held only while this page stays open.</strong> Download your plan before refreshing or closing. This preview does not save to Microsoft.</div><form id="development-plan" data-competency="${c.id}"><div class="plan-grid"><div class="field full"><label for="plan-action">What action will I practice?</label><textarea id="plan-action" data-plan-field="action" maxlength="3000" placeholder="Choose one behavior and describe a practical action…">${esc(p.action)}</textarea></div><div class="field"><label for="plan-support">What support will help?</label><textarea id="plan-support" data-plan-field="support" maxlength="2000" placeholder="A person, resource, or opportunity…">${esc(p.support)}</textarea></div><div class="field"><label for="plan-evidence">How will I recognize progress?</label><textarea id="plan-evidence" data-plan-field="evidence" maxlength="2000" placeholder="A change I can observe or a result I can discuss…">${esc(p.evidence)}</textarea></div><div class="field"><label for="plan-date">When will I check in?</label><input id="plan-date" type="date" data-plan-field="date" value="${esc(p.date)}"></div><div class="field full"><label for="plan-reflection">What did I learn?</label><textarea id="plan-reflection" data-plan-field="reflection" maxlength="3000" placeholder="Return to this after you’ve tried the action…">${esc(p.reflection)}</textarea></div></div><div class="plan-actions"><button class="button" type="button" data-action="download-plan">Download my plan ${icon('arrow')}</button><span class="save-status" id="plan-status" role="status">${Object.values(p).some(Boolean)?'Changes held for this session':'Your plan is ready to start'}</span></div></form></section><p class="source-note">Development planning is separate from performance ratings. Use the downloaded plan in a conversation with your leader.</p>`}
function development(){let c=byId(state.planCompetency);if(!hasRole(c,state.role))state.role=c.group==='senior_leader'?'senior_leader':'people_leader';return heading('MY DEVELOPMENT','Small steps. Meaningful progress.','Choose a competency that matters to your work. Make one practical commitment, then reflect on what you learn.')+`<div class="toolbar"><div class="field search"><label for="plan-competency">Competency to work on</label><select id="plan-competency">${competencies.map(c=>`<option value="${c.id}" ${c.id===state.planCompetency?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="plan-role">Your role</label><select id="plan-role">${roleOptions(state.role,c)}</select></div><a class="text-link" href="#competency/${c.id}">Read the guide ${icon('arrow',17)}</a></div><div id="plan-container">${planForm(c)}</div>`}
function reviews(){return heading('PERFORMANCE REVIEWS','A dedicated workspace for reviews.','Prepare the review, download the summary, and complete the required steps in Oracle.')+`<div class="review-launch panel"><span class="pill">Future review design preview</span><h2 style="margin-top:18px">Explore the review experience.</h2><p>This workspace uses fictional employees to demonstrate role-specific behavior ratings, competency comments, calculated summaries, Word export, and the manual Oracle handoff.</p><div class="notice">${icon('info')}<p>The 2026 evaluation cycle uses the existing process. The design below is for future implementation. Entries last only for this page session; Microsoft and Oracle are not connected.</p></div><ol class="numbered-list"><li>Choose a fictional direct report.</li><li>Rate behaviors and add evidence in the required comments.</li><li>Check the completed review and download Word.</li><li>Follow the Oracle entry, approval, sharing, and coaching steps.</li></ol><button class="button" data-action="launch-review" type="button">${state.reviewFrame?'Resume':'Open'} review workspace ${icon('arrow')}</button><p class="source-note">The draft rubric uses “Needs Improvement” in its rating summary and “Developing” in competency anchors. The workspace retains its summary label and shows the exact anchor wording; final labels still require confirmation.</p></div>`}
function pageForRoute(){const parts=location.hash.slice(1).split('/');const route=parts[0]||'home';if(route==='competencies'){if(parts[1]==='role'&&roles[parts[2]]){state.filter=parts[2];state.role=parts[2];state.group='all'}else if(['core','people_leader','senior_leader'].includes(parts[1])){state.group=parts[1];state.filter='all'}return [route,catalog()]};if(route==='competency'){const c=byId(parts[1]);if(c)return [route,guidePage(c)];return [route,heading('COMPETENCY NOT FOUND','Let’s find the right guide.','This guide link isn’t available.')+'<a class="button" href="#competencies">Explore all competencies</a>']};return [route,{home,stages,development,reviews,leader:()=>window.HUB_RESOURCES.renderLeader(),implementation:()=>window.HUB_RESOURCES.renderImplementation(),resources:()=>window.HUB_RESOURCES.renderResources()}[route]?.()||home()]}
function render({focus=true}={}){document.body.classList.remove('review-open');$('#review-host').hidden=true;const[route,html]=pageForRoute();$('#page-content').innerHTML=html;document.title=(route==='home'?'Southwest Gas Competency Hub':($('#main h1')?.textContent||'Competency Hub')+' | Southwest Gas');document.querySelectorAll('[data-route]').forEach(a=>a.setAttribute('aria-current',a.dataset.route===(route==='competency'?'competencies':route)?'page':'false'));$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');if(focus){$('#main').scrollIntoView({block:'start'});$('#main h1')?.focus({preventScroll:true})}}
function refreshGuide(){const c=currentGuide();if(!c)return;$('#guide-body').innerHTML=guideBody(c);document.querySelectorAll('[data-guide-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.guideTab===state.tab)))}
function announce(t){$('#announcement').textContent=t}
function downloadPlan(){const form=$('#development-plan');if(!form)return;const c=byId(form.dataset.competency),p=getPlan(c);if(!p.action.trim()){$('#plan-status').textContent='Add an action before downloading your plan.';$('#plan-action').focus();return}const title=`${c.name} Development Plan`;const html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{font:16px/1.7 Arial,sans-serif;color:#182848;max-width:800px;padding:35px;margin:auto}header{border-bottom:6px solid #FCCC42;padding-bottom:20px;margin-bottom:30px}h1,h2{color:#121E66}h2{font-size:16px;margin-top:25px}p{white-space:pre-wrap}small{color:#536176}button{background:#121E66;color:white;border:0;border-radius:6px;padding:12px 18px;cursor:pointer}@media print{button{display:none}body{padding:0}}</style><header><small>SOUTHWEST GAS · HUMAN RESOURCES</small><h1>My development plan</h1><strong>${esc(c.name)}</strong> · ${esc(roles[state.role])}</header><p>${esc(c.definition)}</p>${[['My action','action'],['Support I need','support'],['How I’ll recognize progress','evidence'],['Check-in date','date'],['What I learned','reflection']].map(([label,k])=>`<h2>${label}</h2><p>${esc(p[k]||'—')}</p>`).join('')}<hr><small>Development planning is separate from performance ratings. This file is a personal copy of the plan entered in the hub.</small><p><button onclick="window.print()">Print or save as PDF</button></p></html>`;const blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${title} ${new Date().toISOString().replace(/[:.T]/g,' ').replace('Z','')}.html`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#plan-status').textContent='Plan downloaded. Open the file to print or save as PDF.'}
function launchReview(){if(!state.reviewFrame){state.reviewFrame=document.createElement('iframe');state.reviewFrame.className='review-frame';state.reviewFrame.title='Future performance review design workspace';state.reviewFrame.src='Performance Review Workspace Revision 1.html';state.reviewFrame.setAttribute('id','review-frame')};const host=$('#review-host');document.body.classList.add('review-open');host.hidden=false;$('.review-launch').hidden=true;state.reviewFrame.hidden=false;if(!state.reviewFrame.isConnected)host.append(state.reviewFrame);state.reviewFrame.focus();host.scrollIntoView({block:'start'});announce('Review workspace opened. Fictional employee preview.');}
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return}const group=e.target.closest('[data-group]');if(group){state.group=group.dataset.group;document.querySelectorAll('[data-group]').forEach(b=>b.setAttribute('aria-pressed',String(b===group)));$('#catalog-results').innerHTML=catalogResults();return}const t=e.target.closest('[data-guide-tab]');if(t){state.tab=t.dataset.guideTab;refreshGuide();document.querySelector('.tabs [data-guide-tab="'+state.tab+'"]')?.focus();announce('Showing '+state.tab+' section');return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='reset-search'){state.search='';state.group='all';state.filter='all';$('#page-content').innerHTML=catalog();$('#competency-search').focus()}if(action==='download-plan')downloadPlan();if(action==='launch-review')launchReview();if(action==='review-intro'){document.body.classList.remove('review-open');$('#review-host').hidden=true;$('.review-launch').hidden=false;$('.review-launch button').textContent='Resume review workspace';$('.review-launch button').focus()}if(e.target.closest('.menu-toggle')){const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open))}});
document.addEventListener('input',e=>{if(e.target.id==='competency-search'){state.search=e.target.value;$('#catalog-results').innerHTML=catalogResults()}if(e.target.dataset.planField){const c=byId(e.target.closest('form').dataset.competency);state.plans[planKey(c)]={...getPlan(c),[e.target.dataset.planField]:e.target.value};$('#plan-status').textContent='Changes held for this session'}});
document.addEventListener('change',e=>{if(e.target.id==='catalog-role'){state.filter=e.target.value;if(roles[state.filter])state.role=state.filter;$('#catalog-results').innerHTML=catalogResults()}if(e.target.id==='guide-role'){state.role=e.target.value;refreshGuide()}if(e.target.id==='plan-role'){state.role=e.target.value;$('#plan-container').innerHTML=planForm(byId(state.planCompetency))}if(e.target.id==='plan-competency'){state.planCompetency=e.target.value;render({focus:false});$('#plan-competency').focus()}if(e.target.id==='stage-role'){state.role=e.target.value;$('#stage-explore').href='#competencies/role/'+state.role}});
document.addEventListener('submit',e=>{if(e.target.id==='development-plan')e.preventDefault()});
document.addEventListener('keydown',e=>{document.documentElement.classList.add('keyboard-input');if(e.key==='Escape'&&$('#navigation').classList.contains('open')){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').focus()}});document.addEventListener('pointerdown',()=>document.documentElement.classList.remove('keyboard-input'));
window.addEventListener('message',event=>{if(event.origin===location.origin&&state.reviewFrame&&event.source===state.reviewFrame.contentWindow&&event.data?.type==='swg-return-to-hub'){location.hash='home'}});
window.addEventListener('hashchange',()=>{state.tab='behaviors';render()});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon,20));render({focus:false});
})();
